const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");
    const video = document.getElementById("camera");
    const cameraStatus = document.getElementById("cameraStatus");
    const knifeImage = new Image();
    knifeImage.src = "faca_cursor.png";

    // Cenário de madeira fornecido pelo usuário, incorporado ao HTML.
    const backgroundImage = new Image();
    const backgroundCache = document.createElement("canvas");
    const backgroundCacheCtx = backgroundCache.getContext("2d", { alpha: false });
    let backgroundReady = false;
    backgroundImage.onload = () => {
      const rect = canvas.getBoundingClientRect();
      const targetW = Math.max(1, Math.round(rect.width));
      const targetH = Math.max(1, Math.round(rect.height));
      backgroundCache.width = targetW;
      backgroundCache.height = targetH;
      const scale = Math.max(targetW / backgroundImage.width, targetH / backgroundImage.height);
      const sw = backgroundImage.width * scale;
      const sh = backgroundImage.height * scale;
      backgroundCacheCtx.drawImage(backgroundImage, (targetW - sw) / 2, (targetH - sh) / 2, sw, sh);
      backgroundReady = true;
    };
    backgroundImage.src = "data:image/jpeg;base64,";
    function drawBackground() {
      // Cor de base aparece levemente por baixo da madeira.
      ctx.fillStyle = "#4b2a17";
      ctx.fillRect(0, 0, W, H);

      if (backgroundReady) {
        // Opacidade menor deixa o fundo de madeira mais suave.
        ctx.save();
        ctx.globalAlpha = 0.78;
        ctx.drawImage(backgroundCache, 0, 0, W, H);
        ctx.restore();
      }
    }

    const scoreEl = document.getElementById("score");
    const comboEl = document.getElementById("comboValue");
    const goalProgressFill = document.getElementById("goalProgressFill");
    const goalProgressText = document.getElementById("goalProgressText");
    const SCORE_GOAL = 1500;
    const timeEl = document.getElementById("time");
    const message = document.getElementById("message");
    const startBtn = document.getElementById("start");
    const startScreen = document.getElementById("startScreen");
    const menuButton = document.getElementById("menuButton");
    const sensitivityInput = document.getElementById("sensitivity");
    const sensitivityValue = document.getElementById("sensitivityValue");

    // Aumente para o dedo percorrer mais distância na tela.
    let sensitivity = Number(sensitivityInput.value);

    // Suavização: valores menores deixam o cursor mais estável,
    // valores maiores fazem o cursor responder mais rapidamente.
    const smoothing = 0.92;

    sensitivityInput.addEventListener("input", () => {
      sensitivity = Number(sensitivityInput.value);
      sensitivityValue.textContent = `${sensitivity.toFixed(1)}x`;
    });

    let W, H;
    let items = [], particles = [], trails = [[]];
    let score = 0, time = 60, combo = 0;
    let comboHits = 0, lastFruitCutAt = 0, comboFx = null;
    let playing = false;
    let lastSpawn = 0, lastTime = 0;
    let lastBombAt = -Infinity;
    let timer, animation;
    let detector;
    let ultimaLeitura = -1;
    let cameraIniciada = false;
    // Acompanha somente uma mão e a ponta do dedo indicador.
    const maos = [
      { anterior: null, atual: null, suavizado: null }
    ];

    function resize() {
      const rect = canvas.getBoundingClientRect();
      const dpr = Math.min(window.devicePixelRatio || 1, 1.25);
      W = rect.width;
      H = rect.height;
      canvas.width = W * dpr;
      canvas.height = H * dpr;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    }

    window.addEventListener("resize", resize);
    resize();

    function spawn() {
      // Bombas mais raras: chance de 5% e intervalo mínimo de 4 segundos.
      const bomb = Math.random() < 0.05 && performance.now() - lastBombAt > 4000;
      if (bomb) lastBombAt = performance.now();
      const fruits = ["🍉", "🍎", "🍊", "🍍", "🍓", "🥝", "🍌"];

      items.push({
        x: W * (0.25 + Math.random() * 0.5),
        y: H + 30,
        vx: (Math.random() - 0.5) * 3,
        vy: -(10 + Math.random() * 5),
        gravity: 0.15,
        size: 128,
        emoji: bomb ? "💣" : fruits[Math.floor(Math.random() * fruits.length)],
        bomb,
        cut: false,
        rotation: 0
      });
    }

    function burst(item) {
      if (item.bomb) {
        // Onda de choque e clarão exclusivos da bomba.
        particles.push({
          x: item.x, y: item.y, vx: 0, vy: 0,
          life: 32, maxLife: 32, color: "#ffb000",
          ring: true, radius: 12
        });
        for (let i = 0; i < 26; i++) {
          const angle = Math.random() * Math.PI * 2;
          const speed = 3 + Math.random() * 8;
          particles.push({
            x: item.x, y: item.y,
            vx: Math.cos(angle) * speed,
            vy: Math.sin(angle) * speed,
            life: 30, maxLife: 30,
            color: ["#ff3b00", "#ffb000", "#fff36b", "#555"][i % 4],
            size: 3 + Math.random() * 4
          });
        }
        return;
      }

      for (let i = 0; i < 12; i++) {
        particles.push({
          x: item.x,
          y: item.y,
          vx: (Math.random() - 0.5) * 8,
          vy: (Math.random() - 0.5) * 8,
          life: 25,
          color: ["#ff4040", "#ffcc33", "#63e65e"][i % 3]
        });
      }
    }
    function segmentDistance(px, py, x1, y1, x2, y2) {
      const dx = x2 - x1;
      const dy = y2 - y1;
      const len = dx * dx + dy * dy;
      const t = len
        ? Math.max(0, Math.min(1, ((px - x1) * dx + (py - y1) * dy) / len))
        : 0;

      return Math.hypot(px - (x1 + t * dx), py - (y1 + t * dy));
    }

    function moverDedo(indiceMao, x, y) {
      const mao = maos[indiceMao];
      if (!mao) return;

      const adjustedX = Math.max(0, Math.min(1, 0.5 + (x - 0.5) * sensitivity));
      const adjustedY = Math.max(0, Math.min(1, 0.5 + (y - 0.5) * sensitivity));
      const alvo = { x: adjustedX * W, y: adjustedY * H };

      if (!mao.suavizado) {
        mao.suavizado = alvo;
      } else {
        mao.suavizado = {
          x: mao.suavizado.x + (alvo.x - mao.suavizado.x) * smoothing,
          y: mao.suavizado.y + (alvo.y - mao.suavizado.y) * smoothing
        };
      }

      mao.atual = { ...mao.suavizado };
      if (mao.anterior && playing) {
        let frutasCortadas = 0;
        for (const item of items) {
          if (!item.cut && segmentDistance(
            item.x, item.y,
            mao.anterior.x, mao.anterior.y,
            mao.atual.x, mao.atual.y
          ) < item.size * 0.65) {
            item.cut = true;
            burst(item);
            if (item.bomb) {
              time = Math.max(0, time - 5);
              timeEl.textContent = time;
              message.textContent = "💥 Bomba! -5 segundos";
              if (time <= 0) endGame("Tempo esgotado!");
            } else {
              frutasCortadas++;
            }
          }
        }

        if (frutasCortadas > 0) {
          const agora = performance.now();
          const janelaCombo = 850; // cortes dentro de 0,85s formam uma sequência
          if (agora - lastFruitCutAt <= janelaCombo) {
            comboHits += frutasCortadas;
          } else {
            comboHits = frutasCortadas;
          }
          lastFruitCutAt = agora;

          const ganho = frutasCortadas * 10;
          score += ganho;
          let bonus = 0;

          // O combo começa a partir do segundo corte rápido, mesmo em frutas
          // cortadas em movimentos separados (não precisam ser simultâneos).
          if (comboHits >= 2) {
            combo = comboHits;
            bonus = 25;
            score += bonus;
            comboFx = {
              started: agora,
              count: combo,
              points: ganho + bonus
            };
            comboEl.textContent = `x${combo} (+${ganho + bonus} pts)`;
            message.textContent = `🔥 COMBO x${combo}! +${ganho + bonus} pontos!`;
          } else {
            combo = 0;
            comboEl.textContent = "1 corte — continue rápido!";
            message.textContent = "🍉 +10 pontos! Corte outra fruta rapidamente para fazer combo!";
          }

          scoreEl.textContent = score;
          timeEl.textContent = time;
          const progresso = Math.min(100, (score / SCORE_GOAL) * 100);
          goalProgressFill.style.width = `${progresso}%`;
          goalProgressText.textContent = `${Math.min(score, SCORE_GOAL)} / ${SCORE_GOAL}`;
          if (score >= SCORE_GOAL) {
            endGame("🏆 META ALCANÇADA! Você venceu!");
            return;
          }
        }

        trails[indiceMao].push(mao.atual);
        if (trails[indiceMao].length > 12) trails[indiceMao].shift();
      } else {
        trails[indiceMao] = [];
      }
      mao.anterior = mao.atual;
    }

    async function controlarPorDedo(callback) {
      

      // Carrega a biblioteca somente quando a webcam for solicitada.
      const { HandLandmarker, FilesetResolver } = await import(
        "https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.14/vision_bundle.mjs"
      );

      if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
        throw new Error("Webcam indisponível. Abra o jogo por localhost ou HTTPS.");
      }

      // Solicita a webcam primeiro; isso ajuda a identificar bloqueios de permissão.
      const stream = await navigator.mediaDevices.getUserMedia({
        video: {
          facingMode: "user",
          width: { ideal: 320, max: 320 },
          height: { ideal: 240, max: 240 },
          frameRate: { ideal: 30, max: 30 }
        },
        audio: false
      });
      video.srcObject = stream;
      await video.play();
     
      const vision = await FilesetResolver.forVisionTasks(
        "https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.14/wasm"
      );

      const opcoesDetector = {
        baseOptions: {
          modelAssetPath:
            "https://storage.googleapis.com/mediapipe-models/hand_landmarker/hand_landmarker/float16/1/hand_landmarker.task"
        },
        runningMode: "VIDEO",
        numHands: 1,
        minHandDetectionConfidence: 0.55,
        minHandPresenceConfidence: 0.55,
        minTrackingConfidence: 0.5
      };

      // Tenta GPU primeiro; se o navegador não oferecer suporte, usa CPU.
      try {
        detector = await HandLandmarker.createFromOptions(vision, {
          ...opcoesDetector,
          baseOptions: { ...opcoesDetector.baseOptions, delegate: "GPU" }
        });
      
      } catch (gpuError) {
        console.warn("GPU indisponível; usando CPU:", gpuError);
        detector = await HandLandmarker.createFromOptions(vision, {
          ...opcoesDetector,
          baseOptions: { ...opcoesDetector.baseOptions, delegate: "CPU" }
        });
      }

      cameraIniciada = true;
      

      // Atualiza o rastreamento do dedo em até cerca de 30 quadros por segundo.
      // Isso reduz o uso de CPU sem afetar a animação do jogo.
      let ultimaInferencia = 0;
      function atualizar(agora) {
        if (!cameraIniciada) return;
        if (document.hidden) {
          requestAnimationFrame(atualizar);
          return;
        }

        if (
          video.readyState >= 2 &&
          video.currentTime !== ultimaLeitura &&
          agora - ultimaInferencia >= 33
        ) {
          ultimaLeitura = video.currentTime;
          ultimaInferencia = agora;

          const resultado = detector.detectForVideo(video, agora);
          const maoDetectada = resultado.landmarks?.[0];

          if (maoDetectada) {
            const dedoIndicador = maoDetectada[8];
            // Usa somente a ponta do indicador (ponto 8) da primeira mão.
            callback(0, 1 - dedoIndicador.x, dedoIndicador.y);
            
          } else {
            maos[0].anterior = null;
            maos[0].atual = null;
            maos[0].suavizado = null;
            trails[0] = [];
          
          }
        }

        requestAnimationFrame(atualizar);
      }

      requestAnimationFrame(atualizar);
    }

    function draw(now) {
      if (!playing) return;

      const dt = Math.min((now - (lastTime || now)) / 16.67, 2);
      lastTime = now;
      ctx.clearRect(0, 0, W, H);
      drawBackground();

      // Animação especial de combo: texto pulsante, brilho e anéis dourados.
      if (comboFx) {
        const age = now - comboFx.started;
        const progress = Math.min(1, age / 850);
        const alpha = 1 - progress;
        const pulse = 1 + Math.sin(age / 55) * 0.09;
        ctx.save();
        ctx.globalAlpha = alpha;
        ctx.translate(W / 2, H * 0.34 - progress * 38);
        ctx.scale(pulse, pulse);
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";
        ctx.font = "bold 46px go";
        ctx.lineWidth = 8;
        ctx.strokeStyle = "#7a2600";
        ctx.strokeText(`COMBO x${comboFx.count}!`, 0, 0);
        ctx.fillStyle = "#ffe45c";
        ctx.shadowColor = "#ff7b00";
        ctx.shadowBlur = 24;
        ctx.fillText(`COMBO x${comboFx.count}!`, 0, 0);
        ctx.font = "bold 20px go";
        ctx.fillStyle = "#ffffff";
        ctx.fillText(`+${comboFx.points} PONTOS  •  +${comboFx.seconds}s`, 0, 38);
        ctx.restore();

        ctx.save();
        ctx.globalAlpha = alpha * 0.8;
        ctx.strokeStyle = "#ffd84a";
        ctx.lineWidth = 5 * alpha + 1;
        for (let ring = 0; ring < 3; ring++) {
          const radius = 35 + progress * 145 + ring * 18;
          ctx.beginPath();
          ctx.arc(W / 2, H * 0.34, radius, 0, Math.PI * 2);
          ctx.stroke();
        }
        ctx.restore();
        if (progress >= 1) comboFx = null;
      }

      if (now - lastSpawn > 700) {
        spawn();
        if (Math.random() < 0.35) spawn();
        lastSpawn = now;
      }

      items.forEach(item => {
        item.x += item.vx * dt;
        // Mantém as frutas na área central, evitando que escapem pelos cantos.
        const limiteLateral = W * 0.12;
        if (item.x < limiteLateral) {
          item.x = limiteLateral;
          item.vx = Math.abs(item.vx);
        } else if (item.x > W - limiteLateral) {
          item.x = W - limiteLateral;
          item.vx = -Math.abs(item.vx);
        }
        item.y += item.vy * dt;
        item.vy += item.gravity * dt;
        item.rotation += 0.03 * dt;

        if (!item.cut) {
          ctx.save();
          ctx.translate(item.x, item.y);
          ctx.rotate(item.rotation);
          ctx.font = `${item.size}px Arial`;
          ctx.textAlign = "center";
          ctx.textBaseline = "middle";
          ctx.fillText(item.emoji, 0, 0);
          ctx.restore();
        }
      });

      items = items.filter(item => {
        if (item.cut) return false;

        if (item.y > H + 70) {
          return false;
        }
        return true;
      });

      particles.forEach(p => {
        p.x += p.vx * dt;
        p.y += p.vy * dt;
        if (!p.ring) p.vy += 0.15 * dt;
        p.life -= dt;

        ctx.globalAlpha = Math.max(0, p.life / (p.maxLife || 25));
        if (p.ring) {
          p.radius += 9 * dt;
          ctx.strokeStyle = p.color;
          ctx.lineWidth = 7 * ctx.globalAlpha;
          ctx.beginPath();
          ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
          ctx.stroke();
        } else {
          ctx.fillStyle = p.color;
          ctx.beginPath();
          ctx.arc(p.x, p.y, p.size || 5, 0, Math.PI * 2);
          ctx.fill();
        }
      });

      ctx.globalAlpha = 1;
      particles = particles.filter(p => p.life > 0);

      const coresMaos = ["#67e8f9"];
      maos.forEach((mao, i) => {
        const rastro = trails[i];
        if (rastro.length > 1) {
          ctx.beginPath();
          ctx.moveTo(rastro[0].x, rastro[0].y);
          rastro.forEach(p => ctx.lineTo(p.x, p.y));
          ctx.strokeStyle = coresMaos[i];
          ctx.lineWidth = 6;
          ctx.lineCap = "round";
          ctx.shadowColor = coresMaos[i];
          ctx.shadowBlur = 15;
          ctx.stroke();
          ctx.shadowBlur = 0;
          rastro.shift();
        }
        if (mao.atual && knifeImage.complete && knifeImage.naturalWidth) {
          const larguraFaca = 112;
          const alturaFaca = larguraFaca * knifeImage.height / knifeImage.width;
          ctx.save();
          ctx.drawImage(knifeImage, mao.atual.x - larguraFaca * 0.48,
            mao.atual.y - alturaFaca * 0.52, larguraFaca, alturaFaca);
          ctx.restore();
        }
      });

      animation = requestAnimationFrame(draw);
    }

    function endGame(text) {
      if (!playing) return;

      playing = false;
      clearInterval(timer);
      cancelAnimationFrame(animation);

      const venceu = score >= SCORE_GOAL;
      message.textContent = `${text} Pontuação: ${score}`;
      startBtn.textContent = venceu ? "JOGAR NOVAMENTE" : "TENTAR NOVAMENTE";
      startBtn.textContent = "JOGAR NOVAMENTE";
      startScreen.style.display = "flex";

      ctx.fillStyle = "rgba(0,0,0,0.65)";
      ctx.fillRect(0, 0, W, H);
      ctx.fillStyle = "#FFFFFF";
      ctx.font = "bold 50px go";
      ctx.textAlign = "center";
      ctx.fillText("FIM DE JOGO!", W / 2, H / 2 - 15);
      ctx.fillStyle = "white";
      ctx.font = "bold 22px go";
      ctx.fillText(`Pontos: ${score}`, W / 2, H / 2 + 25);
    }

    function returnToMenu() {
      playing = false;
      clearInterval(timer);
      cancelAnimationFrame(animation);
      startBtn.disabled = false;
      startBtn.textContent = "JOGAR";
      startScreen.style.display = "flex";
      message.textContent = "Escolha JOGAR para começar uma nova partida.";
      comboFx = null;
      comboHits = 0;
      lastFruitCutAt = 0;
    }

    menuButton.addEventListener("click", returnToMenu);

    function startGame() {
      startScreen.style.display = "none";
      clearInterval(timer);
      cancelAnimationFrame(animation);

      items = [];
      particles = [];
      trails = [[]];
      maos.forEach(mao => {
        mao.anterior = null;
        mao.atual = null;
        mao.suavizado = null;
      });

      score = 0;
      time = 60;
      combo = 0;
      comboHits = 0;
      lastFruitCutAt = 0;
      comboFx = null;
      comboEl.textContent = "0";
      lastTime = 0;
      lastSpawn = 0;
      lastBombAt = -Infinity;
      playing = true;

      scoreEl.textContent = score;
      timeEl.textContent = time;
      goalProgressFill.style.width = "0%";
      goalProgressText.textContent = `0 / ${SCORE_GOAL}`;
      startBtn.textContent = "REINICIAR";

      timer = setInterval(() => {
        if (!playing) return;
        time--;
        timeEl.textContent = time;
        if (time <= 0) endGame("Tempo esgotado!");
      }, 1000);

      animation = requestAnimationFrame(draw);
    }

    startBtn.addEventListener("click", async () => {
      // Inicia o jogo imediatamente, sem esperar a webcam/modelo carregar.
      startGame();
      if (cameraIniciada) return;

      startBtn.disabled = true;
      cameraStatus.textContent = "WEBCAM LIGADA";
      try {
        await controlarPorDedo(moverDedo);
        message.textContent = "Mova a faquinha com o dedo indicador para cortar as frutas!";
      } catch (erro) {
        console.error("Falha ao iniciar a webcam/detector:", erro);
        cameraStatus.textContent = "Câmera indisponível";
        message.textContent =
          `O jogo está rodando, mas o controle pela câmera falhou: ${erro?.message || erro}. Abra pelo Live Server, permita a câmera e confira a internet.`;
      } finally {
        startBtn.disabled = false;
      }
    });
